function evidence(st,name,effectId,detail={}){st.__alpha558Evidence=arr(st.__alpha558Evidence);const e={card:name,effectId:Number(effectId)||0,turn:turn(st),...detail};st.__alpha558Evidence.push(e);return e}
function inc(st,k,n=1){st.analysis=st.analysis||{};st.analysis[k]=(Number(st.analysis[k])||0)+n}
function cardByName(name){return arr(W.CARD_CATALOG).find(c=>norm(c?.name)===norm(name))||null}
function findItem(st,p,zs,pred){for(const z of zs){const it=zone(st,p,z).find(pred);if(it)return locate(st,it.uid)}return null}
function pushTrigger(st,item,effectId,sourceZone,createdEvent,mandatory=false){if(!item)return;st.triggerQueue=arr(st.triggerQueue);const key=`${item.uid}|${effectId}|${createdEvent||''}`;if(st.triggerQueue.some(x=>`${x.uid}|${x.effectId}|${x.createdEvent||x.eventId||''}`===key))return;st.triggerQueue.push({player:item.controller??item.owner??0,uid:item.uid,effectId,mandatory,createdEvent:createdEvent||'A558',controller:item.controller??item.owner??0,sourceZone})}
function queueSummonTriggers(st,it,eventId,method='SPECIAL_SUMMON'){if(!it)return;const n=norm(nameOf(it));if(n==='mementotlan shleepy')pushTrigger(st,it,2,'monster',eventId,false);if(n==='mitsurugi no mikoto saji')pushTrigger(st,it,1,'monster',eventId,false)}
function queueTributeTriggers(st,it,eventId){if(!it)return;const n=norm(nameOf(it));if(n==='mitsurugi no mikoto saji')pushTrigger(st,it,1,'gy',eventId,false);if(n==='ame no habakiri no mitsurugi')pushTrigger(st,it,2,'gy',eventId,false)}
function destroyedByEffectThisTurn(st,p){return arr(st?.events).some(e=>String(e?.type).toUpperCase()==='DESTROY'&&(e?.effect===true||/EFFECT/i.test(raw(e?.reason||e?.source||'')))&&(Number(e?.player)===p||Number(e?.fromPlayer)===p||Number(e?.item?.owner)===p||Number(e?.owner)===p))}
function makeEffect(id,rawText,{condition='',activation='',resolution='',costs=[],timing={},restriction={},kind='OTHER',semantic={}}={}){return{id,raw:rawText,condition,activation,resolution,costs,targets:[],restriction:{oncePerTurn:false,oncePerChain:false,oncePerDuel:false,onlyOnce:false,locations:[],summonLocks:[],typeLocks:[],phaseLocks:[],...restriction},timing:{quick:false,trigger:false,damageStep:false,ignition:false,phase:[],...timing},steps:[{text:resolution||rawText,conjunction:'start',mandatory:true}],kind,semantic:{draw:false,search:false,summon:false,special:false,destroy:false,banish:false,send:false,return:false,negate:false,damage:false,target:false,continuous:false,replacement:false,...semantic},alpha558Official:true}}
