const BASE_PARSE=typeof R.parseCard==='function'?R.parseCard.bind(R):null;
function parseCard558(c){const base=BASE_PARSE?BASE_PARSE(c):{card:c,text:raw(c?.desc||c?.text),effects:[],metadata:{}},key=norm(base?.card?.name||c?.name);const f=OFFICIAL[key];return f?{...base,effects:f(base.card),alpha558Official:true}:base}
if(BASE_PARSE&&!R.parseCard.__alpha558){const fn=function(c){return parseCard558(c)};fn.__alpha558=true;fn.__base=BASE_PARSE;R.parseCard=fn}
function createLink(st,p,c,uid,effectId){st.chain=arr(st.chain);const link={id:st.chain.length+1,player:p,uid,card:c.name,effectId,targetUids:[],costsPaid:[],status:'CHAIN LINK',activatedAt:{turn:turn(st),phase:st.phase},spellSpeed:2,alpha558Exact:true};st.chain.push(link);st.priority=1-p;st.window={kind:'CHAIN',open:true};inc(st,'actions');inc(st,'successfulActivations');return link}
function exactActivate558(st,p,c,uid,effectId,costChoices=[]){const n=norm(c?.name),q=locate(st,uid);if(!q||q.p!==p)return{ok:false,reason:'La carta no está bajo tu control.'};if(used(st,p,c.name,effectId)||usedDuel(st,p,c.name,effectId))return{ok:false,reason:'El efecto ya fue usado conforme a su límite.'};
 if(n==='arias the labrynth butler'){if(effectId===1){if(!/^MAIN [12]$/.test(raw(st.phase)))return{ok:false,reason:'Arias sólo puede usar este efecto durante la Main Phase.'};if(!['hand','monster'].includes(q.z))return{ok:false,reason:'Arias debe estar en mano o Campo.'};if(!moveUid(st,uid,'gy',q.item.owner??p))return{ok:false,reason:'No se pudo enviar Arias al GY como coste.'};mark(st,p,c.name,1);return{ok:true,link:createLink(st,p,c,uid,1)}}if(effectId===2){if(q.z!=='gy')return{ok:false,reason:'Arias debe estar en el GY.'};mark(st,p,c.name,2);return{ok:true,link:createLink(st,p,c,uid,2)}}}
 if(n==='labrynth chandraglier'){if(effectId===1){if(!['hand','monster'].includes(q.z))return{ok:false,reason:'Chandraglier debe estar en mano o Campo.'};const other=costChoices.map(id=>locate(st,id)).find(x=>x&&x.p===p&&x.z==='hand'&&String(x.item.uid)!==String(uid))||findItem(st,p,['hand'],x=>String(x.uid)!==String(uid));if(!other)return{ok:false,reason:'Chandraglier requiere descartar 1 carta adicional.'};if(!moveUid(st,uid,'gy',q.item.owner??p)||!moveUid(st,other.item.uid,'gy',other.item.owner??p))return{ok:false,reason:'No se pudo pagar envío + descarte.'};mark(st,p,c.name,1);return{ok:true,link:createLink(st,p,c,uid,1)}}if(effectId===2){if(q.z!=='gy')return{ok:false,reason:'Chandraglier debe estar en el GY.'};mark(st,p,c.name,2);return{ok:true,link:createLink(st,p,c,uid,2)}}}
 if(n==='mementotlan shleepy'){if(effectId===1){if(q.z!=='hand')return{ok:false,reason:'Shleepy debe estar en la mano.'};if(!destroyedByEffectThisTurn(st,p))return{ok:false,reason:'Shleepy requiere que un monstruo en tu posesión haya sido destruido por efecto este turno.'};mark(st,p,c.name,1);return{ok:true,link:createLink(st,p,c,uid,1)}}if(effectId===2){if(q.z!=='monster')return{ok:false,reason:'Shleepy debe estar en el Campo tras ser Invocado.'};mark(st,p,c.name,2);return{ok:true,link:createLink(st,p,c,uid,2)}}if(effectId===3){if(q.z!=='gy')return{ok:false,reason:'Shleepy destruido debe estar en el GY.'};mark(st,p,c.name,3);return{ok:true,link:createLink(st,p,c,uid,3)}}}
 if(n==='mementotlan fusion'){if(effectId===1){if(!/^MAIN [12]$/.test(raw(st.phase)))return{ok:false,reason:'Mementotlan Fusion se activa durante la Main Phase.'};if(q.z!=='spelltrap')return{ok:false,reason:'Mementotlan Fusion debe estar activada en la Zona M/T.'};mark(st,p,c.name,1);return{ok:true,link:createLink(st,p,c,uid,1)}}if(effectId===2){if(q.z!=='gy')return{ok:false,reason:'El segundo efecto de Mementotlan Fusion sólo se activa en el GY.'};if(!moveUid(st,uid,'banished',q.item.owner??p,{faceUp:true}))return{ok:false,reason:'No se pudo desterrar Mementotlan Fusion como coste.'};mark(st,p,c.name,2);return{ok:true,link:createLink(st,p,c,uid,2)}}}
 if(n==='ame no habakiri no mitsurugi'){if(effectId===1){if(q.z!=='hand')return{ok:false,reason:'Habakiri debe estar en la mano para revelarse.'};if(usedDuel(st,p,c.name,1))return{ok:false,reason:'Habakiri ya usó este efecto una vez por Duelo.'};markDuel(st,p,c.name,1);return{ok:true,link:createLink(st,p,c,uid,1)}}if(effectId===2){if(q.z!=='gy')return{ok:false,reason:'Habakiri Sacrificado debe estar en el GY.'};mark(st,p,c.name,2);return{ok:true,link:createLink(st,p,c,uid,2)}}}
 if(n==='mitsurugi no mikoto saji'&&effectId===1){if(!['monster','gy'].includes(q.z))return{ok:false,reason:'Saji debe estar en Campo o GY tras el evento que dispara su efecto.'};mark(st,p,c.name,1);return{ok:true,link:createLink(st,p,c,uid,1)}}
 return null}
const BASE_ACTIVATE=typeof R.activate==='function'?R.activate.bind(R):null;if(BASE_ACTIVATE&&!R.activate.__alpha558){const fn=function(st,p,c,uid,effectId,targets=[],costChoices=[]){if(TARGETS.has(norm(c?.name))){const x=exactActivate558(st,p,c,uid,effectId,costChoices);if(x)return x}return BASE_ACTIVATE(st,p,c,uid,effectId,targets,costChoices)};fn.__alpha558=true;fn.__base=BASE_ACTIVATE;R.activate=fn}
function resolveArias(st,p,link){if(link.effectId===1){if(freeMonster(st,p)){const q=findItem(st,p,['hand'],x=>isMonster(x)&&isArch(x,'Labrynth')&&norm(nameOf(x))!=='arias the labrynth butler');if(q){const it=moveUid(st,q.item.uid,'monster',p,{faceUp:true,position:'ATK'});it.specialSummoned=true;it.summonType='EFFECT';const ev=pushEvent(st,'SPECIAL_SUMMON',{player:p,uid:it.uid,item:it,source:'Arias the Labrynth Butler'});inc(st,'successfulSummons');queueSummonTriggers(st,it,ev.id);return{ok:true,branch:'SUMMON',summoned:nameOf(it)}}}if(freeST(st,p)){const q=findItem(st,p,['hand'],x=>isNormalTrap(x));if(q){const it=moveUid(st,q.item.uid,'spelltrap',p,{faceUp:false});it.__alpha558CanActivateSetTurn=true;return{ok:true,branch:'SET_TRAP',set:nameOf(it)}}}return{ok:false,reason:'Arias no tiene un objetivo legal en la mano.'}}if(link.effectId===2){const q=locate(st,link.uid);if(!q||q.z!=='gy'||!freeMonster(st,p))return{ok:false,reason:'Arias no puede revivir desde el GY.'};const it=moveUid(st,link.uid,'monster',p,{faceUp:true,position:'ATK'});it.specialSummoned=true;const ev=pushEvent(st,'SPECIAL_SUMMON',{player:p,uid:it.uid,item:it,source:'Arias the Labrynth Butler'});inc(st,'successfulSummons');queueSummonTriggers(st,it,ev.id);return{ok:true,summoned:nameOf(it)}}}
function resolveChand(st,p,link){if(link.effectId===1){if(!freeST(st,p))return{ok:false,reason:'No hay Zona M/T libre.'};const q=findItem(st,p,['deck','hand'],x=>(isSpell(x)||isTrap(x))&&isArch(x,'Labrynth'));if(!q)return{ok:false,reason:'No hay Mágica/Trampa Labrynth legal para Colocar.'};const it=moveUid(st,q.item.uid,'spelltrap',p,{faceUp:false});return{ok:true,set:nameOf(it)}}if(link.effectId===2){const q=locate(st,link.uid);if(!q||q.z!=='gy')return{ok:false,reason:'Chandraglier ya no está en el GY.'};const it=moveUid(st,link.uid,'hand',p);return{ok:true,returned:nameOf(it)}}}
function mementoFusionTarget(st,p,count){const extra=zone(st,p,'extra');let q=extra.find(x=>norm(nameOf(x))==='mementotlan twin dragon'&&count>=2);if(!q)q=extra.find(x=>norm(nameOf(x))==='mementomictlan tecuhtlica creation king'&&count>=3);return q?locate(st,q.uid):null}
function resolveShleepy(st,p,link){if(link.effectId===1){const q=locate(st,link.uid);if(!q||q.z!=='hand'||!freeMonster(st,p))return{ok:false,reason:'Shleepy no puede Invocarse desde la mano.'};const it=moveUid(st,link.uid,'monster',p,{faceUp:true,position:'ATK'});it.specialSummoned=true;it.summonType='EFFECT';const ev=pushEvent(st,'SPECIAL_SUMMON',{player:p,uid:it.uid,item:it,source:'Mementotlan Shleepy'});inc(st,'successfulSummons');queueSummonTriggers(st,it,ev.id);return{ok:true,summoned:nameOf(it)}}if(link.effectId===2){const mats=[...zone(st,p,'hand'),...zone(st,p,'monster')].filter(x=>isMonster(x)&&isArch(x,'Memento'));const tq=mementoFusionTarget(st,p,mats.length);if(!tq)return{ok:false,reason:'No hay Fusion Memento o materiales suficientes.'};const need=norm(nameOf(tq.item))==='mementotlan twin dragon'?2:3,chosen=mats.slice(0,need);if(chosen.length<need)return{ok:false,reason:'Faltan materiales Memento.'};const ids=chosen.map(x=>x.uid);for(const uid of ids){const q=locate(st,uid);if(q)moveUid(st,uid,'gy',q.item.owner??p)}const target=moveUid(st,tq.item.uid,'monster',p,{faceUp:true,position:'ATK'});target.summonType='FUSION_SUMMON';target.wasProperlySummoned=true;target.materialsUsed=ids;const ev=pushEvent(st,'FUSION_SUMMON',{player:p,uid:target.uid,item:target,materials:ids,source:'Mementotlan Shleepy'});inc(st,'successfulSummons');queueSummonTriggers(st,target,ev.id,'FUSION_SUMMON');return{ok:true,fusion:nameOf(target),materials:ids}}if(link.effectId===3){const q=findItem(st,p,['deck'],x=>isArch(x,'Memento')&&norm(nameOf(x))!=='mementotlan shleepy');if(!q)return{ok:false,reason:'No hay carta Memento válida en Deck.'};const it=moveUid(st,q.item.uid,'gy',q.item.owner??p);pushEvent(st,'SEND',{player:p,uid:it.uid,item:it,source:'Mementotlan Shleepy'});return{ok:true,sent:nameOf(it)}}}
function resolveMementoFusion(st,p,link){if(link.effectId===1){const mats=[...zone(st,p,'hand'),...zone(st,p,'monster')].filter(x=>isMonster(x));const mem=mats.filter(x=>isArch(x,'Memento'));if(!mem.length)return{ok:false,reason:'La Fusión debe incluir un monstruo Memento.'};const tq=mementoFusionTarget(st,p,mem.length);if(!tq)return{ok:false,reason:'No hay Fusion Memento compatible.'};const need=norm(nameOf(tq.item))==='mementotlan twin dragon'?2:3;let chosen=[mem[0],...mats.filter(x=>x.uid!==mem[0].uid)].slice(0,need);if(chosen.length<need)return{ok:false,reason:'Faltan materiales para Fusionar.'};const ids=chosen.map(x=>x.uid);for(const uid of ids){const q=locate(st,uid);if(q)moveUid(st,uid,'gy',q.item.owner??p)}const target=moveUid(st,tq.item.uid,'monster',p,{faceUp:true,position:'ATK'});target.summonType='FUSION_SUMMON';target.wasProperlySummoned=true;target.materialsUsed=ids;const ev=pushEvent(st,'FUSION_SUMMON',{player:p,uid:target.uid,item:target,materials:ids,source:'Mementotlan Fusion'});inc(st,'successfulSummons');queueSummonTriggers(st,target,ev.id,'FUSION_SUMMON');return{ok:true,fusion:nameOf(target),materials:ids}}if(link.effectId===2){const q=findItem(st,p,['monster'],x=>true);if(!q)return{ok:false,reason:'No controlas monstruo para destruir.'};const it=moveUid(st,q.item.uid,'gy',q.item.owner??p);const ev=pushEvent(st,'DESTROY',{player:p,fromPlayer:p,uid:it.uid,item:it,effect:true,reason:'Mementotlan Fusion',source:'Mementotlan Fusion'});if(norm(nameOf(it))==='mementotlan shleepy')pushTrigger(st,it,3,'gy',ev.id,false);const add=findItem(st,p,['deck'],x=>(isSpell(x)||isTrap(x))&&isArch(x,'Memento'));if(!add)return{ok:false,reason:'No hay Mágica/Trampa Memento para añadir.'};const got=moveUid(st,add.item.uid,'hand',p);inc(st,'searches');return{ok:true,destroyed:nameOf(it),added:nameOf(got)}}}
function resolveHabakiri(st,p,link){if(link.effectId===1){if(!freeMonster(st,p))return{ok:false,reason:'No hay Zona de Monstruos libre.'};let q=findItem(st,p,['deck'],x=>isMonster(x)&&isArch(x,'Mitsurugi')&&norm(nameOf(x))==='mitsurugi no mikoto saji');if(!q)q=findItem(st,p,['deck'],x=>isMonster(x)&&isArch(x,'Mitsurugi'));if(!q)return{ok:false,reason:'No hay monstruo Mitsurugi en Deck.'};const it=moveUid(st,q.item.uid,'monster',p,{faceUp:true,position:'ATK'});it.specialSummoned=true;const sev=pushEvent(st,'SPECIAL_SUMMON',{player:p,uid:it.uid,item:it,source:'Ame no Habakiri no Mitsurugi'});inc(st,'successfulSummons');queueSummonTriggers(st,it,sev.id);let tq=findItem(st,p,['monster'],x=>norm(nameOf(x))==='mitsurugi no mikoto saji')||findItem(st,p,['monster'],x=>true);if(!tq)return{ok:false,reason:'No hay monstruo que Sacrificar después de la Invocación.'};const tr=moveUid(st,tq.item.uid,'gy',tq.item.owner??p);const tev=pushEvent(st,'TRIBUTE',{player:p,previousController:p,controller:p,uid:tr.uid,item:tr,card:nameOf(tr),source:'Ame no Habakiri no Mitsurugi'});queueTributeTriggers(st,tr,tev.id);return{ok:true,summoned:nameOf(it),tributed:nameOf(tr)}}if(link.effectId===2){const add=findItem(st,p,['deck'],x=>isArch(x,'Mitsurugi')&&norm(nameOf(x))!=='ame no habakiri no mitsurugi');if(!add)return{ok:false,reason:'No hay otra carta Mitsurugi en Deck.'};const got=moveUid(st,add.item.uid,'hand',p);inc(st,'searches');let revived=null;const q=locate(st,link.uid);if(q?.z==='gy'&&freeMonster(st,p)){revived=moveUid(st,link.uid,'monster',p,{faceUp:true,position:'ATK'});if(revived){revived.specialSummoned=true;const ev=pushEvent(st,'SPECIAL_SUMMON',{player:p,uid:revived.uid,item:revived,source:'Ame no Habakiri no Mitsurugi'});inc(st,'successfulSummons');queueSummonTriggers(st,revived,ev.id)}}return{ok:true,added:nameOf(got),revived:nameOf(revived)}}}
function resolveSaji(st,p,link){if(link.effectId!==1)return{ok:false,reason:'Efecto de Saji no activable en esta ruta.'};const q=findItem(st,p,['deck'],x=>(isSpell(x)||isTrap(x))&&isArch(x,'Mitsurugi'));if(!q)return{ok:false,reason:'No hay Mágica/Trampa Mitsurugi en Deck.'};const it=moveUid(st,q.item.uid,'hand',p);inc(st,'searches');return{ok:true,added:nameOf(it)}}
